import sys
lines = sys.stdin.read().splitlines()
out = []
stk = []
min_stk = []
if lines:
    m = int(lines[0])
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'PUSH':
            v = int(cmd[1])
            stk.append(v)
            min_stk.append(v if not min_stk or v < min_stk[-1] else min_stk[-1])
        elif cmd[0] == 'POP':
            stk.pop(); min_stk.pop()
        elif cmd[0] == 'TOP': out.append(str(stk[-1]))
        elif cmd[0] == 'GETMIN': out.append(str(min_stk[-1]))
print(' '.join(out))
